def _on_main():
    results: list = []
    statuses: list = []
    errors: list = []

    if atomic and HOU_AVAILABLE:
        hou.undos.beginGroup()

    try:
        for i, cmd_spec in enumerate(commands):
            cmd_type = cmd_spec.get("type", "")
            cmd_payload = cmd_spec.get("payload", {})
            handler = self._registry.get(cmd_type)

            if handler is None:
                err = f"Step {i}: unknown command '{cmd_type}'"
                errors.append(err)
                statuses.append("error")
                results.append(None)
                if stop_on_error:
                    break
                continue

            try:
                result = handler(cmd_payload)
                results.append(result)
                statuses.append("ok")
                errors.append(None)
            except Exception as e:
                results.append(None)
                statuses.append("error")
                errors.append(f"Step {i}: {e}")
                if stop_on_error:
                    break
    finally:
        if atomic and HOU_AVAILABLE:
            hou.undos.endGroup()

    return {
        "results": results,
        "statuses": statuses,
        "errors": errors,
    }

