            raise ValueError(
                "That node doesn't have an active USD stage yet -- "
                "it may need to cook first, or check the LOP network is set up"
            )

        root_prim = stage.GetPrimAtPath(root_path)
        if not root_prim.IsValid():
            raise ValueError(
                f"Couldn't find a prim at {root_path} -- "
                "double-check the path on the USD stage"
            )

        from pxr import Usd, UsdGeom

        # Optional name pattern matching
        import re
        name_re = None
        if name_pattern:
            try:
                name_re = re.compile(name_pattern, re.IGNORECASE)
            except re.error:
                # Treat as simple substring match if not valid regex
                name_re = None

        results = []

        def _walk(prim, depth):
            if depth > max_depth or len(results) >= limit:
                return

            path_str = str(prim.GetPath())
            prim_type_name = prim.GetTypeName()

            # Apply filters
            if prim_type and prim_type_name != prim_type:
                # Also check if it's a subclass match
                if not prim.IsA(Usd.Typed):
                    pass  # Continue walking children
                elif prim_type_name and prim_type.lower() not in prim_type_name.lower():
                    pass  # Skip but still walk children
                else:
                    # Exact type filter didn't match — skip this prim
                    for child in prim.GetChildren():
                        _walk(child, depth + 1)
                    return

            if purpose:
                imageable = UsdGeom.Imageable(prim)
                if imageable:
