                    for child in prim.GetChildren():
                        _walk(child, depth + 1)
                    return

            # Prim passes all filters — collect it
            entry = {
                "path": path_str,
                "type": prim_type_name,
                "name": prim.GetName(),
            }

            # Add optional metadata
            kind = Usd.ModelAPI(prim).GetKind()
            if kind:
                entry["kind"] = str(kind)

            imageable = UsdGeom.Imageable(prim)
            if imageable:
                p = imageable.ComputePurpose()
                if p:
                    entry["purpose"] = str(p)
                vis = imageable.ComputeVisibility()
                if vis:
                    entry["visibility"] = str(vis)

            if prim.IsActive():
                entry["active"] = True
            else:
                entry["active"] = False

            results.append(entry)

            # Walk children
            for child in prim.GetChildren():
                _walk(child, depth + 1)

        _walk(root_prim, 0)

        return {
            "root_path": root_path,
            "prim_count": len(results),
            "prims": results,
            "truncated": len(results) >= limit,
        }

    return run_on_main(_on_main)

